WITH src AS (SELECT *, DATE_FORMAT(opened_date, 'yyyy-MM-dd') AS opened_date_label FROM stores WHERE opened_date <= '2023-06-01' AND UPPER(store_name) LIKE '%IRP%' AND region = 'Central'), stores_stats AS (SELECT DATE_TRUNC('MONTH', opened_date) AS opened_month, MIN(opened_date) AS min_opened_date, ROUND(STDDEV(sqft), 2) AS stddev_sqft FROM src GROUP BY DATE_TRUNC('MONTH', opened_date)) SELECT opened_month, min_opened_date, stddev_sqft FROM stores_stats WHERE stddev_sqft > 61;
